# =================================================================
# MAPA EXCLUSIVO DE TEXTOS (leyendas)
# ARCHIVO GENERADO AUTOMÁTICAMENTE A PARTIR DE LA DEFINICIÓN: layers.04_denue.01_capas_escuelas 
# DESCRIPCIÓN: Escuelas primarias en el estado de Veracruz 
# =================================================================

LAYER
  NAME "t_denue_escuelas_primarias"
  STATUS ON
  TYPE POINT
  CONNECTIONTYPE POSTGIS
  CONNECTION "host=mxsig-db port=5432 dbname=mdm6data user=postgres password=P0stgr3s"
  DATA "the_geom FROM (SELECT gid, the_geom, nombre_ue FROM denue.escuelas_primarias) AS t1 USING UNIQUE gid USING SRID=900913"
  METADATA
    "wms_title" "Texto Escuelas primarias (DENUE 2026)"
    "wms_enable_request" "*"
  END
  LABELITEM "nombre_ue"
  CLASS
    LABEL
      FONT "arial"
      SIZE 8
      COLOR 0 0 0
      OUTLINECOLOR 255 255 255
      POSITION auto
      TYPE truetype
    END
  END
END

